import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
		String[] scanner = r.readLine().split(" ");
		int ans = Integer.parseInt(scanner[0]);
		int bb = Integer.parseInt(scanner[1]);
		System.out.println(countHug(ans, bb));

	}

	public static int countHug(int ans, int bb) {
		if (ans == bb) return ans;
		else if (ans < bb) {
			return countHug(ans, bb - ans);
		}
		else return countHug(ans - bb, ans);
	}
}

