public class Main {
    private static final Scanner max = new Scanner(System.in);

    public static void main(String[] args) {
        int targetNumbers = max.nextInt(), zeroCount = max.nextInt();
        System.out.println(isPrimeNumber(targetNumbers > zeroCount ? targetNumbers : zeroCount, targetNumbers < zeroCount ? targetNumbers : zeroCount));
    }

    private static int isPrimeNumber(int targetNumbers, int zeroCount) {
        if(zeroCount > 0) {
            return isPrimeNumber(zeroCount, targetNumbers % zeroCount);
        } else {
            return targetNumbers;
        }
    }
}

import java.util.*;

public class Main {
	static Scanner sub = new Scanner(System.in);
	public static void main(String[] args) {
		int kind = sub.nextInt();
		int integers = sub.nextInt();
		System.out.println(run(kind,integers));
	}
	//最大公約数gcdを求める
	static int run (int arg, int bob) {
		int temp;
		while((temp = arg%bob)!=0) {
			arg = bob;
			bob = temp;
		}
		return bob;
	}
}

