public class Main{

    public static void main(String[] args)throws IOException{
        BufferedReader str = new BufferedReader(new InputStreamReader(System.in));
        String[] target = str.readLine().split(" ");
        int aa = Integer.parseInt(target[0]);
        int ts = Integer.parseInt(target[1]);
        System.out.println(checkPrimeNumber(aa, ts));
    }

    public static int  checkPrimeNumber(int commonDiviserList, int indexA){
        int tokenizer;
        if(commonDiviserList < indexA){
            int taste;
            taste = commonDiviserList;
            commonDiviserList = indexA;
            indexA = taste;
        }

        while(indexA > 0){
            tokenizer = commonDiviserList % indexA;
            commonDiviserList = indexA;
            indexA = tokenizer;
        }
        return commonDiviserList;
    }

}

