class Main{
    //読み込みのテンプレ(stringオブジェクトまで)
    public static void main(String[] args) throws IOException{
        BufferedReader tokenizer = new BufferedReader(new InputStreamReader(System.in));
        String currentCardPositionOfThePlayer = tokenizer.readLine();
        StringTokenizer currentCardPositionOfB = new StringTokenizer(currentCardPositionOfThePlayer," ");

        int currentCardPositionOfA = Integer.parseInt((String)currentCardPositionOfB.nextElement());
        int arrayCnt = Integer.parseInt((String)currentCardPositionOfB.nextElement());

        int lineCount = isOdd(currentCardPositionOfA,arrayCnt);
        System.out.println(lineCount);
    }

    public static int isOdd(int currentCardPositionOfA,int arrayCnt){

        int lineCount;

        if(currentCardPositionOfA > arrayCnt){

            while(currentCardPositionOfA%arrayCnt != 0 || arrayCnt !=1){
                int stack = currentCardPositionOfA;
                int ans1 = arrayCnt;
                currentCardPositionOfA = arrayCnt;
                arrayCnt = stack % arrayCnt;

                if(arrayCnt == 0){
                    arrayCnt = ans1;
                    break;
                }
            }
            if(arrayCnt == 1){
                lineCount = 1;
            }else{
                lineCount = arrayCnt;
            }


        }else{
            int searchSize = currentCardPositionOfA;
            int y_x = arrayCnt;

            currentCardPositionOfA = y_x;
            arrayCnt = searchSize;

            while(currentCardPositionOfA%arrayCnt !=0 || arrayCnt !=1){
                int stack = currentCardPositionOfA;
                int ans1 = arrayCnt;
                currentCardPositionOfA = arrayCnt;
                arrayCnt = stack % arrayCnt;
                if(arrayCnt == 0){
                    arrayCnt = ans1;
                    break;
                }
            }
            if(arrayCnt == 1){
                lineCount = 1;
            }else{
                lineCount = arrayCnt;
            }

        }
        return lineCount;
    }
}

