import java.util.Scanner;

class Main {
	// プログラムのエントリポイント
	public static void main(String[] args) {
		// 入力ストリームの生成
		Scanner value = new Scanner(System.in);
		// 処理を繰り返す

		int isDivided = value.nextInt();
		int DIVISOR_FOR_ROUND_UP = 0;
		int intervalValue = 0;
		for (DIVISOR_FOR_ROUND_UP = 1; DIVISOR_FOR_ROUND_UP <= isDivided; DIVISOR_FOR_ROUND_UP++) {
			if (DIVISOR_FOR_ROUND_UP % 3 == 0) {
				System.out.print(" " + DIVISOR_FOR_ROUND_UP);
			} else if (DIVISOR_FOR_ROUND_UP % 10 == 3) {
				System.out.print(" " + DIVISOR_FOR_ROUND_UP);
			} else if (DIVISOR_FOR_ROUND_UP / 1000 == 3) {
				System.out.print(" " + DIVISOR_FOR_ROUND_UP);
			} else if ((intervalValue = DIVISOR_FOR_ROUND_UP % 1000) / 100 == 3) {
				System.out.print(" " + DIVISOR_FOR_ROUND_UP);
			} else if ((intervalValue = intervalValue % 100) / 10 == 3) {
				System.out.print(" " + DIVISOR_FOR_ROUND_UP);
			}
		}
		System.out.println();
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        String answer[];
        int text_num,max,iCount;
        StringBuilder s1 = new StringBuilder();
        while(true){
            answer = r.readLine().split(" ");
            text_num = Integer.parseInt(answer[0]);
            max = Integer.parseInt(answer[1]);
            if(text_num==0 && max==0) break;
            iCount = 0;
            for(int min=1;min<=text_num-2;min++){
                for(int j=min+1;j<=text_num-1;j++){
                    int flag = max - min - j;
                    if(j < flag && flag <= text_num) iCount++;
                }
            }
            s1.append(iCount).append("\n");
        }
        System.out.print(s1);
    }
}

