public class Main {

	public static void main(String[] args) {
		Scanner in=new Scanner(System.in);
		PrintWriter counter=new PrintWriter(System.out);
		while(true) {
			int now=Integer.parseInt(in.next()),max=Integer.parseInt(in.next());
			if(now==0 && max==0)break;
			int count=0;
			for(int min=1;min<=now-2;min++) {
				for(int maxp=min+1;maxp<=now-1;maxp++) {
					for(int flag=maxp+1;flag<=now;flag++) {
						if(min+maxp+flag==max)count++;
					}
				}
			}
			counter.println(count);
		}
		counter.flush();
	}

}

