import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner check = new Scanner(System.in);
		while (check.hasNextInt()) {
			int arr = check.nextInt();
			int total = check.nextInt();
			int c = 0;
			if (arr == 0 && total == 0) return;

			for (int minCost = 1; minCost <= arr; ++minCost) {
				for (int inclued3 = minCost + 1; inclued3 <= arr; ++inclued3) {
					for (int amount = inclued3 + 1; amount <= arr; ++amount) {
						int max = minCost + inclued3 + amount;
						if (max == total) {
							c++;
						} else if (max > total) {
							break;
						}
					}
				}
			}
			System.out.println(c);
		}
	}
}

import java.util.*;
import java.lang.StringBuilder;
public class Main {
	public static void main(String[] args) throws Exception{
		Scanner scan = new Scanner(System.in);
		StringBuilder sub = new StringBuilder();
		int ch = 0;
		int now,length;
		do{
			now = scan.nextInt();
			length = scan.nextInt();
			ch = 0;
			if(now==0&&length==0){
				break;
			}
			for(int sam = 1;sam <= now;sam++){
				for(int hit = 1;hit <= now;hit++){
					if(hit==sam){
						break;
					}
					for(int flag = 1;flag <= now;flag++){
						if(sam==flag){
							break;
						}else if(hit==flag){
							break;
						}else if(sam+hit+flag==length){
							++ch;
						}
					}
				}
			}
			sub.append(ch).append("\n");
		}while(true);
		System.out.print(sub);
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner age = new Scanner(System.in);
        int variance, l, mouth = 0;

        for(;;){
            variance = age.nextInt();
            l = age.nextInt();
            if(variance == 0 && l == 0) break;
            for(int x1 = 1; x1 < variance; x1++){
                for(int t2 = x1+1; t2 < variance; t2++){
                    for(int t = t2+1; t <= variance; t++){
                        if(x1+t2+t==l) mouth+=1;
                    }
                }
            }
            System.out.println(mouth);
            mouth = 0;
        }
    }
}

