import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sum = new Scanner(System.in);

        while (true) {
            int array = sum.nextInt();
            int list = sum.nextInt();
            if (array == 0 && list == 0) break;
            int counter = 0;


            for (int h = 1; h < array; ++h) {
                for (int total = h; total < array; ++total) {
                    if (h == total) continue;
                    int inclued3 = list - (h + total);
                    if (inclued3 < 1) break;
                    if (inclued3 < total) break;
                    if (h != inclued3 && total != inclued3 && inclued3 <= array) counter++;
                    inclued3 = 0;
                }
            }
            System.out.println(counter);
        }
    }
}

