import java.util.*;

class Main{
	public static void main(String[] args){
		Scanner s= new Scanner(System.in);
		while(true){
			String[] master =s.nextLine().split(" ");
			int scanner = Integer.parseInt(master[0]);
			int cards = Integer.parseInt(master[1]);
		//break	
			if(scanner==0 && cards==0){
				break;
			}
			System.out.println(gcd(scanner,cards));
		}					

	}
	public static int gcd(int scanner,int cards){
		int res=0;
		for(int minAbs=0;minAbs<scanner;minAbs++){
			for(int distanceBase=0;distanceBase<minAbs;distanceBase++){
				for(int flooredDistance=0;flooredDistance<distanceBase;flooredDistance++){
					if(cards-3==minAbs+distanceBase+flooredDistance){
						res=res+1;
					}
				}
			}
		}
		return res;
	}
}

