        // finish
        if(nijou == 0 && finished == 0) break;
        // check
        for(int each_mozi = 1; each_mozi <= nijou; each_mozi++){
          for(int queue = (each_mozi + 1); (each_mozi + queue) < finished; queue++){
            int max = finished - each_mozi - queue;
            if(max > queue && max <= nijou) part++;
          }
        }
        s1.append(part + "\n");
      }
      // output
      System.out.print(s1);
    }catch(Exception lineList){
      System.out.println(lineList);
    }
  }
}

