/**
n×m  の行列 A  と m×l  の行列 B  を入力し、それらの積である n×l  の
 を出力するプログラムを作成してください。行列 C  の各要素 c ij   は次の式で得られます：

 １行目に n 、m 、l  が空白区切りで与えられます。

続く行に n×m  の行列 A  と m×l  の行列 B  が与えられます。

 */

//スキャナつかうため

import java.util.Scanner;

public class Main {
	// プログラムのエントリポイント
	public static void main(String[] args) {
		// 入力ストリームの生成
		Scanner maxL = new Scanner(System.in);
		// 3つの数値を受け取る
		int inputs = maxL.nextInt();
		int instance = maxL.nextInt();
		int other = maxL.nextInt();
		// 受け取った数値で配列をつくる
		// Aの行列
		int[][] currentHeights = new int[inputs][instance];
		// Bの行列
		int[][] strEzura = new int[instance][other];
		// Cの行列
		long[][] gyouc = new long[inputs][other];
		// 数値をAの配列の数受け取る
		for (int each_mozi = 0; each_mozi < inputs; each_mozi++) {
			for (int mark = 0; mark < instance; mark++) {
				currentHeights[each_mozi][mark] = maxL.nextInt();
			}
		}
		// Bの配列の数数値を受け取る
		for (int each_mozi = 0; each_mozi < instance; each_mozi++) {
			for (int mark = 0; mark < other; mark++) {
				strEzura[each_mozi][mark] = maxL.nextInt();
			}
		}
		// 計算
		for (int each_mozi = 0; each_mozi < inputs; each_mozi++) {
			for (int mark = 0; mark < other; mark++) {

				for (int aCardMaxLen = 0; aCardMaxLen < instance; aCardMaxLen++) {
					// Cの配列に計算結果を入れていく
					gyouc[each_mozi][mark] += currentHeights[each_mozi][aCardMaxLen] * strEzura[aCardMaxLen][mark];
				}
				System.out.print(gyouc[each_mozi][mark]);
				if (mark != other - 1) {
					// 空白
					System.out.print(" ");
				}
			}
			// 改行
			System.out.println();
		}

	}
}

