class intArr {
   private final BufferedReader buffer;
   private StringTokenizer countMax;

    intArr(InputStream filter) {
        buffer = new BufferedReader(new InputStreamReader(filter));
    }

    String nextLine() {
        while (countMax == null || !countMax.hasMoreTokens()) {
            try {
                countMax = new StringTokenizer(buffer.readLine());
            } catch (IOException parent) {
                throw new RuntimeException(parent);
            }
        }
        return countMax.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextLine());
    }

    long nextLong() {
        return Long.parseLong(nextLine());
    }

    double nextLongArrayOneBased() {
        return Double.parseDouble(nextLine());
    }



    ArrayList<Integer> nextDoubleArray(int count) {
        ArrayList<Integer> head = new ArrayList<>();
        for (int nq = 0; nq < count; nq++) {
            int number = nextInt();
            head.add(number);
        }
        return head;
    }

    int[] nextToken(int count) {
        int[] head = new int[count];
        for (int nq = 0; nq < count; nq++) {
            head[nq] = nextInt();
        }
        return head;
    }
}

