        public ns(InputStream s2Length) {
            this.stream = s2Length;
        }

        public int reversebits() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (scanner >= numChars) {
                scanner = 0;
                try {
                    numChars = s2Length.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[scanner++];
        }

        public int readBody() {
            int set = reversebits();
            while (compare(set)) {
                set = reversebits();
            }
            int cardS = 1;
            if (set == '-') {
                cardS = -1;
                set = reversebits();
            }
            int res = 0;
            do {
                if (set < '0' || set > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += set - '0';
                set = reversebits();
            } while (!compare(set));
            return res * cardS;
        }

        public boolean compare(int set) {
            if (ret != null) {
                return ret.isSpaceChar(set);
            }
            return MyInput(set);
        }

