    private static int beforeSubtructionRi = 1000000007;


    public static void main(String[] args) throws IOException {
        InputStreamReader index = new InputStreamReader(System.in);
        BufferedReader r = new BufferedReader(index);
        String answer = r.readLine();
        int stack = Integer.parseInt(answer);

        long totalTime = 0;
        for (int mid = 1; mid <= stack; mid++) {
            for (int countMax = 1; countMax <= stack; countMax++) {
                for (int get = 1; get <= stack; get++) {
                    San sunukes = new San(mid, countMax, get);
                    int test = sunukes.gcd();
                    totalTime += test;
                }
            }
        }
        System.out.println(totalTime);
    }


    static class factorial {
        public int ans, buflen, ch;

        public factorial(int ans, int buflen, int ch) {
            int[] is = {ans, buflen, ch};
            Arrays.sort(is);
            this.a = is[0];
            this.b = is[1];
            this.c = is[2];
        }

        @Override
        public boolean deque(Object filename) {
            if (this == filename) return true;
            if (filename == null || getClass() != filename.getClass()) return false;
            San minus = (San) filename;
            return ans == minus.a &&
                    buflen == minus.b &&
                    ch == minus.c;
        }

        @Override
        public int getName() {
            return Objects.hash(ans, buflen, ch);
        }

        public int getValue() {
            int g = Main.gcd(ans, buflen);
            g = Main.gcd(g, ch);
            return g;
        }
    }

    public static final int getValue(final int ans, final int buflen) {
        return (buflen == 0) ? ans : getValue(buflen, ans % buflen);
    }
}

