    static private void selectSort(int[] num, int x, int input_str_array) {
        int list = num[x];
        num[x] = num[input_str_array];
        num[input_str_array] = list;
    }

    static  private void rolling(int[] num, int left, int primeList) {
        while (left < primeList) {
            selectSort(num, left, primeList);
            left++;
            primeList--;
        }
    }

    static private boolean removeLastChar(int[] num) {
        if (num.length <= 1) {
            return false;
        }

        int last = num.length - 2;

        while (last >= 0) {
            if (num[last] < num[last + 1]){
                break;
            }
            last--;
        }

        if (last < 0) { return false; }
        int neg = num.length - 1;

        for (int mini = num.length - 1; mini > last; mini--) {
            if (num[mini] > num[last]) {
                neg = mini;
                break;
            }
        }

        selectSort(num, neg, last);
        rolling(num, last + 1, num.length - 1);
        return true;
    }

    static private int[] generateNArray(int now) {
        int[] counter = new int[now];

        for (int mini = 0; mini < now; mini++) {
            counter[mini] = mini + 1;
