        for(int a=1;a<=stack;a++){
            for(int buff1=1;buff1<=stack;buff1++){
                for(int ts=1;ts<=stack;ts++){
                    ans2 += getMod(getMod(a,buff1),ts);
                }
            }
        }
        return ans2;
    }
    int getMod(int a, int buff1){
        if(a<buff1){
            int ts = a; a=buff1;buff1=ts;
        }
        while(a%buff1!=0){
            int ts = buff1; buff1=a%buff1;a=ts;
        }
        return buff1;
    }
