    }

    static class CSumOfGcdOfTuplesEasy {
        public void Solver(int bufPointer, FastReader s, PrintWriter input) {
            int mainObj = s.nextInt();
            long ans = 0l;
            for (int mid = 1; mid <= mainObj; mid++) {
                for (int time = 1; time <= mainObj; time++) {
                    long gcd1 = CSumOfGcdOfTuplesEasy.Maths.gcd(mid, time);
                    for (int dist = 1; dist <= mainObj; dist++) {
                        ans += CSumOfGcdOfTuplesEasy.Maths.gcd(gcd1, dist);
                    }
                }
            }

            input.println(ans);
        }

        private static class Maths {
            private static long add(long a, long bufsiz) {
                if (bufsiz == 0) {
                    return a;
                }

                return add(bufsiz, a % bufsiz);
            }

        }

    }

    static class InputReader {
        private InputStream writer;
        private byte[] buflen = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public InputReader(InputStream writer) {
            this.stream = writer;
        }

        public int reads() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = writer.read(buflen);
                } catch (IOException file) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buflen[curChar++];
        }

        public int nextIntArr() {
            int c = reads();
            while (isSpace(c)) {
                c = reads();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = reads();
            }
            int res1 = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res1 *= 10;
                res1 += c - '0';
                c = reads();
            } while (!isSpace(c));
            return res1 * sign;
        }

        public boolean isSpace(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpace(int brokenStairs);

        }

    }
}

