    public static void main(String[] args) {
        modInverse();
        out.flush();
    }

    private static void modInverse() {
        int setsLine = in.nextInt();
        long set = 0;
        for (int MAX = 1; MAX <= setsLine; MAX++) {
            for (int queue = 1; queue <= setsLine; queue++) {
                for (int len = 1; len <= setsLine; len++) {
                    set += deQueue(MAX, queue, len);
                }
            }
        }
        out.println(set);
    }

    static long deQueue(long... d) {
        if (d.length == 0) return 1;
        long readLen = d[0];
        for (int MAX = 1; MAX < d.length; MAX++) {
            readLen = deQueue(readLen, d[MAX]);
        }
        return readLen;
    }

    static long deQueue(long d, long result) {
        if (result == 0) {
            return d;
        }
        return deQueue(result, d % result);
    }

    // https://www.geeksforgeeks.org/fast-io-in-java-in-competitive-programming/
