                    if(s == cell && cell ==fixed)
                    {
                        bd += s;
                    }
                    else
                    {
                        //最大公約数を求める
                        int Ltemp = dig(s,cell,fixed);
                        bd += Ltemp;
                    }
                }
            }
        }
        System.out.println(bd);
    }

    public static int dig(int apple,int nowX, int more) {
        if(apple < nowX)
        {
            int Ltemp = apple;
            apple = nowX;
            nowX = Ltemp;
        }
        int now = 0;
        while(( now = apple % nowX) != 0)
        {
            apple = nowX;
            nowX = now;
        }

        if(nowX < more)
        {
            int Ltemp = nowX;
            nowX = more;
            more = Ltemp;
        }
        while((now = nowX % more) != 0)
        {
            nowX = more;
            more = now;
        }
        return more;
    }
}

