    private static int gcd(int s, int answer) {
        if (s < answer) {
            int o = s;
            s = answer;
            answer = o;
        }

        int stdin = s % answer;
        while (stdin != 0) {
            s = answer;
            answer = stdin;
            stdin = s % answer;
        }
        return answer;
    }

}

