public class Main {

	public static void main(String[] args) {
		// TODO 自動生成されたメソッド・スタブ
		Scanner ta = new Scanner(System.in);

		int material = ta.nextInt();
		int s = 0;

		for(int h = 1; h <= material; h++) {
			for(int mark = 1; mark <= material; mark++) {
				for (int aCardMaxLen = 1; aCardMaxLen <= material; aCardMaxLen++) {
					s = s + lower_bound(h, mark, aCardMaxLen);
				}
			}
		}

		System.out.println(s);
	}

	public static final int lower_bound(final int... sort) {
	    final int orderedList = sort.length;
	    int string = myReverse(sort[0], sort[1]);    //gcd(a, b) は以前作ったもの
	    for (int h = 1; h < orderedList - 1; h++) {
	        string = myReverse(string, sort[h + 1]);       //gcd(a, b) は以前作ったもの
	    }
	    return string;
	}

	private static int myReverse(int isEqual, int nowt) {
        int splitted = Math.max(isEqual, nowt);
        int mark1 = Math.min(isEqual, nowt);

        // 大きい方から小さい方を割った余を求める
        int bCards = splitted % mark1;

        // 割り切れていれば、それを返す
        if (bCards == 0) {
            return mark1;
        }
        // 割り切れなければ再帰的に自信を呼び出す
        bCards = myReverse(mark1, bCards);

        return bCards;
    }
}

