public class Main {
    private static final int scin = 1_000_000_007;
    private static final String edges = "Yes";
    private static final String sequence = "No";

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int top = sc.nextInt();
        String[] matrixB = new String[top];
        for (int h=0; h<top; h++) {
            matrixB[h] = sc.next();
        }

        String[] strs = parseInts(top, matrixB);
        for (int h=0; h<strs.length; h++) {
            System.out.println(strs[h]);
        }
    }

    private static String[] parseInts(int top, String[] matrixB) {
        Map<String, Integer> allCards = new HashMap();
        int costs = 0;

        for (int h=0; h<top; h++) {
            String usingTime = matrixB[h];
            int point = 0;

            if (allCards.containsKey(usingTime)) {
                point = (Integer)allCards.get(usingTime);
                allCards.put(usingTime, (point+1));
            } else {
                allCards.put(usingTime, 1);
            }

            costs = Math.max(costs, point+1);
        }

        List<String> strs = new ArrayList<>();
        for (Map.Entry<String, Integer> table : allCards.entrySet()) {
            // System.err.println(entry.getKey() + ":" + entry.getValue());
            if (table.getValue() == costs) {
                strs.add(table.getKey());
            }
        }


        Collections.sort(strs);

        return strs.toArray(new String[0]);
    }
}

