import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner score = new Scanner(System.in);
        int less = Integer.parseInt(score.next());
        long result = Long.parseLong(score.next());
        int tryangle = Integer.parseInt(score.next());

        int[] answerR = new int[tryangle];
        for (int ml = 0; ml < tryangle; ml++) {
            answerR[ml] = Integer.parseInt(score.next());
        }

        // 合っている人のみ抽出
        int[] Args = new int[less];
        for (int ml = 0; ml < tryangle; ml++) {
            int end = answerR[ml];
            Args[end - 1]++;
        }

        // 最大点数で初期化
        long[] queue = new long[less];
        for (int ml = 0; ml < less; ml++) {
            queue[ml] = result;
        }

        // 合ってるポイント分減算して減らす
        for (int ml = 0; ml < less; ml++) {
            int arr2 = Args[ml];
            int data = tryangle - arr2;

            queue[ml] -= data;
        }

        for (int ml = 0; ml < less; ml++) {
            System.out.println(queue[ml] > 0 ? "Yes" : "No");
        }
    }
}

