                testNumber.println("Yes");
            }
            else {
                testNumber.println("No");
            }
        }
        testNumber.flush();
    }

    private static void shuffle(int [] al, int totalTime, int readLine) {
        if(totalTime == readLine) {
            List<Integer> list = new ArrayList<>();
            for(int s_i : al) list.add(s_i);
            root.add(list);
        }
        else {
            for (int s_i = totalTime; s_i <=readLine; s_i++) {
                getDigitSum(al,totalTime,s_i);
                shuffle(al,totalTime+1,readLine);
                getDigitSum(al,totalTime,s_i);
            }
        }
    }
    private static void getDigitSum(int [] al, int totalTime, int readLine) {
        int target = al[totalTime];
        al[totalTime] = al[readLine];
        al[readLine] = target;
    }

}
