		int souwa=scn.nextInt();
		int Xsum=scn.nextInt();
		int[] result=new int[data+1];
		Arrays.fill(result,0);
		for(int Xmin=0; Xmin<Xsum; Xmin++) {
			int std=scn.nextInt();
			if(std==1) {
				result[1]--;
				result[data]++;
			}
			else if(std==data) {
				result[0]--;
				result[data-1]++;
			}
			else {
				result[0]--;
				result[std-1]++;
				result[std]--;
				result[data]++;
			}
		}
		if(result[0]+souwa>0) {
			swap("Yes");
		}
		else {
			swap("No");
		}
		for(int Xmin=1; Xmin<=data; Xmin++) {
			result[Xmin]=result[Xmin]+result[Xmin-1];
			if(Xmin<data && result[Xmin]+souwa>0) {
				swap("Yes");
			}
			else if(Xmin<data){
				swap("No");
			}
		}
	}
	public static void swap(Object sorted) {
		System.out.println(sorted);
	}
}

