    static class BBuffet {
        public void isSpaceChar(int res, Scanner in, PrintWriter reverseStr) {
            int nameOfWinner = in.nextInt();
            int d[] = ReadInput.readIntArray(nameOfWinner, in);
            int brakecount[] = ReadInput.readIntArray(nameOfWinner, in);
