          solver = (char)system;
          system = longSortedArr();
        }while(!MScanner(system));
        return solver;
      }

      public int nextInt() {
          int system = longSortedArr();
          while (MScanner(system))
              system = longSortedArr();
          int qTime = 1;
          if (system == '-') {
              qTime = -1;
              system = longSortedArr();
          }
          int cst = 0;
          do {
              if (system < '0' || system > '9')
                  throw new InputMismatchException();
              cst *= 10;
              cst += system - '0';
              system = longSortedArr();
          } while (!MScanner(system));
          return cst * qTime;
      }

