    static long substring(long twentySix, long five) {
        if(five == 0)
            return 1;
        if(five % 2 == 0) {
            long inf = substring(twentySix, five / 2);
            return inf * inf % third;
        }else {
            return twentySix * substring(twentySix, five - 1) % third;
        }
    }

    static long rolling(long marks, long b) {
        if(b > marks - b)
            return rolling(marks, marks - b);
        long bufLength = 1;
        long ps = 1;
        long en;
        for(en = 0; en < b; en++) {
            bufLength *= (marks - en);
            bufLength %= third;
            ps *= (en + 1);
            ps %= third;
        }
        long result = bufLength * substring(ps, third - 2) % third;
        return result;
    }
