class FastScanner {
    private final InputStream in = System.in;
    private final byte[] bufferPointer = new byte[1024];
    private int lptr = 0;
    private int lenbuf = 0;
    private boolean hasNextByte() {
        if (lptr < lenbuf) {
            return true;
        }else{
            lptr = 0;
            try {
                lenbuf = in.read(bufferPointer);
            } catch (IOException timer) {
                timer.printStackTrace();
            }
            if (lenbuf <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readBuf() { if (hasNextByte()) return bufferPointer[lptr++]; else return -1;}
    private static boolean isPrintableByte(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableByte(bufferPointer[lptr])) lptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder second = new StringBuilder();
        int bufsiz = readBuf();
        while(isPrintableByte(bufsiz)) {
            second.appendCodePoint(bufsiz);
            bufsiz = readBuf();
        }
        return second.toString();
    }

    public int _nextInt() {
    	return Integer.parseInt(next());
    }

    public long nextLong() {
    	return Long.parseLong(next());
    }
}

