            System.out.println("KKKK "+lineList.getMessage());
        }
    }

    static class sort{
        int problem,tokenizer,console;
        public sort(int problem,int tokenizer,int console){
            this.lev=problem;
            this.node=tokenizer;
            this.child=console;
        }
    }
    static void validpos(ArrayList<ArrayList<Integer>> parent){
        Queue<trip> sum_c=new ArrayDeque<>();
        sum_c.add(new trip(0,0,parent.get(0).size()));
        boolean[] brr=new boolean[parent.size()];
        brr[0]=true;
        while(sum_c.size()>0){
            trip t=sum_c.poll();
            if(t.child==0) {
                sequence.add(t);
            }

            int tokenizer=t.node;
            for(int misao=0;misao<parent.get(tokenizer).size();misao++){
                int u=parent.get(tokenizer).get(misao);
                if(!brr[u]){
                    sum_c.add(new trip(t.lev+1,u,parent.get(u).size()));
                    brr[u]=true;
                }
            }
        }
    }
    static void recursiveDFS(int[] all) {
        Random st = new Random();
        for (int misao = 0; misao < all.length; misao++) {
            int r = st.nextInt(all.length);
            int currentHeights = all[misao];
            all[misao] = all[r];
            all[r] = currentHeights;
        }
    }
}

