public class Main{
    public static void main(String[] args){
      Scanner scan = new Scanner(System.in);
      int now = scan.nextInt();
      int max = scan.nextInt();
      int[] ans = new int[max];
      int[] dist = new int[now+3];
      Set<Integer> start = new HashSet<Integer>();
      for(int mini = 0;mini < max;mini++){
        ans[mini] = scan.nextInt();
        start.add(ans[mini]);
      }
      dist[0] = 0;
      if(start.contains(1)){
        dist[1]=0;
      }else dist[1]=1;
      if(start.contains(2)){
      	dist[2]=0;
      }else dist[2] = dist[1]+1;
      for(int mini = 3;mini <= now;mini++){
      	if(start.contains(mini)) dist[mini]=0;
        else dist[mini]=(dist[mini-1]+dist[mini-2])%1000000007;
      }
      System.out.println(dist[now]);
    }
    public static int calc_gcd_lcm(int x, int table){
      return x*table/gcd(x,table);
    }
    public static int gcd(int x, int table){
      if(x < table)return gcd(table,x);
      if(table==0)return x;
      return gcd(table,x%table);
    }
}

