class Main {
    public static void main(String[] args) {
        Scanner sum_c = new Scanner(System.in);
        int pow = 1000000007;
        int tempArray = sum_c.nextInt();
        int max = sum_c.nextInt();
        long p[] = new long[100100];
        Arrays.fill(p, 0);
        p[0] = 0;
        p[1] = 0;
        p[2] = 1;
        p[3] = 1;
        p[4] = 2;
        p[5] = 3;
        for (int tri = 6; tri < 100100; tri++) {
            p[tri] = (p[tri - 1] + p[tri - 2]) % pow;
        }
        int acs[] = new int[max];
        for (int tri = 0; tri < max; tri++) {
            acs[tri] = sum_c.nextInt();
        }
        sum_c.close();
        if (max == 0) {
            // System.out.println(n + 2);
            System.out.println(p[tempArray + 2]);
            return;
        }
        for (int tri = 0; tri < max - 1; tri++) {
            int minN = acs[tri + 1] - acs[tri];
            if (minN == 1) {
                System.out.println(0);
                return;
            }
        }
        long ts = 1;
        ts *= p[acs[0] + 1];

        for (int tri = 1; tri < max; tri++) {
            int minN = acs[tri] - acs[tri - 1];
            // System.out.println(sa);
            ts = ts * p[minN] % pow;
        }
