public class Main {
    static int mincost = 1000000007;
    public static void main(String[] args) throws Exception {
        // Your code here!
        Scanner sum = new Scanner(System.in);

        int nowX = sum.nextInt();
        int mod = sum.nextInt();
        int[] stdin = new int[mod];
        for (int li = 0; li < mod; li++) {
            stdin[li] = sum.nextInt();

            if (li > 0 && stdin[li] - stdin[li - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long waResultCount = 1;

        for (int li = 0; li < mod; li++) {
            int tastes = stdin[li];
            waResultCount = waResultCount * prime((tastes - 1) - oldNum) % mincost;
            oldNum = tastes + 1;
        }

        waResultCount = waResultCount * prime(nowX - oldNum) % mincost;

        System.out.println(waResultCount);
    }

    public static long prime(long nowX) {
        long number = 1;
        long num2 = 1;
        long target = 1;

        for (long li = 1; li < nowX; li++) {
            target = (number + num2) % mincost;
            number = num2;
            num2 = target;
        }

        return target;
    }
}

