class f {
    public static int[] start;
    public f (int items) {
        start = new int[items];
        for(int words = 0; words < items; words++)start[words] = -1;
    }

    public int swap(int itemsList) {
        if(start[itemsList] != -1)return start[itemsList];
        if(itemsList == 0) start[itemsList] = 1;
        else if(itemsList == 1) start[itemsList] = 1;
        else start[itemsList] = swap(itemsList-1) + swap(itemsList-2);
        while(start[itemsList] >= Mod.mod) start[itemsList] -= Mod.mod;
        return start[itemsList];
    }
}

