import java.util.*;

public class Main{
    public static void main(String[] args){
        Scanner stack = new Scanner(System.in);
        int now = stack.nextInt();
        int max = stack.nextInt();
        boolean[] ans2 = new boolean[now];
        long[] end = new long[now];

        for (int flag=0;flag<now;flag++){
            ans2[flag] = false;
            end[flag] = 0;
        }

        for (int Xmin=0;Xmin<max;Xmin++){
            int ac_count = stack.nextInt();
            ans2[ac_count-1] = true;
        }

        if (now == 1){
            if (max == 1){
                System.out.println(0);
            }
            else{
                System.out.println(1);
            }
            return;
        }
        long sum2 = 0;
        end[0] = 1;
        end[1] = 1;
        if (ans2[0] == true){
            end[1] = 0;
        }
        sum2 = binarySearch(2, now, ans2, end);
        long height = 1000000007;
        System.out.println((long) sum2 % height);
    }

    static long binarySearch(int cant, int now, boolean[] ans2, long[] end){

        if (cant == now){
            return end[now-1]+end[now-2];
        }

        if (ans2[cant-1] == true){
            end[cant] = 0;
        }
        else{
            end[cant] = end[cant-1] + end[cant-2];
        }
        long height = 1000000007;
        end[cant] = (long) end[cant] % height;
        return (long) binarySearch(cant + 1, now, ans2, end);
    }
}

