import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int Args=sc.nextInt(),right=sc.nextInt();
		long[] way = new long[Args+1];
		boolean[] broken = new boolean[Args+1];
		for(int dMin=0;dMin<right;dMin++) broken[sc.nextInt()]=true;
		for(int dMin=0;dMin<=Args;dMin++) way[dMin]=-1;
		way[0]=1;
		if(broken[1]) way[1]=0;
		else way[1]=1;
		System.out.println(Main(Args,broken,way));
	}

	static long Main(int Args, boolean[] broken, long[] way) {
		final long d = 1000000007;
		if(broken[Args]) return 0;
		if(way[Args]!=-1) return way[Args];
		else{
			way[Args] = (Main(Args-1,broken,way)+Main(Args-2,broken,way))%d;
			return way[Args];
		}
	}
}

