                    divisiors.add(mid);
                }
            }
        }

    }

    static class IntegerUtils {
        public static int get_time(int ans, int bufsiz) {
            ans = Math.abs(ans);
            bufsiz = Math.abs(bufsiz);
            while (bufsiz != 0) {
                int target = ans % bufsiz;
                ans = bufsiz;
                bufsiz = target;
            }
            return ans;
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buflen = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter bufPointer;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int reads() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buflen);
                } catch (IOException pre) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buflen[curChar++];
        }

        public int readInt() {
            int c = reads();
            while (isSpace(c)) {
                c = reads();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = reads();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = reads();
            } while (!isSpace(c));
            return res * sign;
        }

        public boolean isSpace(int c) {
            if (bufPointer != null) {
                return bufPointer.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpace(int brokenStairs);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void isPow() {
            writer.close();
        }

        public void isPrintableChar(int mid) {
            writer.println(mid);
        }

    }
}

