public class Main {

    static int sum, ms, tmp2;

    public static void main(String[] args) {
        FastScanner total = new FastScanner(System.in);
        sum = total.nextInt();
        ms = total.nextInt();
        tmp2 = total.nextInt();

        System.out.println(shuffle());
    }

    static int shuffle() {
        int from = Math.max(sum, ms);
        int total_time = 0;
        for (int h = Math.max(sum, ms); h >= 1; h--) {
            if( sum%h==0 && ms%h==0 ) total_time++;
            if( total_time == tmp2 ) return h;
        }
        return -1;
    }

    @SuppressWarnings("unused")
    static class ContestScanner {
        private BufferedReader bufferedReader;
        private StringTokenizer scanner;

        ContestScanner(InputStream in) {
            bufferedReader = new BufferedReader(new InputStreamReader(in));
            scanner = null;
        }

        String nextIntArr() {
            if (scanner == null || !scanner.hasMoreTokens()) {
                try {
                    scanner = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException line) {
                    throw new RuntimeException(line);
                }
            }
            return scanner.nextToken();
        }

        String nextLongArr() {
            if (scanner == null || !scanner.hasMoreTokens()) {
                try {
                    return bufferedReader.readLine();
                } catch (IOException line) {
                    throw new RuntimeException(line);
                }
            }
            return scanner.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(nextIntArr());
        }

        int nextInt() {
            return Integer.parseInt(nextIntArr());
        }

        int[] nextArray(int n3) {
            int[] asciiCodes = new int[n3];
            for (int h = 0; h < n3; h++)
                asciiCodes[h] = nextInt();
            return asciiCodes;
        }

        int[] nextArray(int n3, int stack) {
            int[] asciiCodes = new int[n3];
            for (int h = 0; h < n3; h++)
                asciiCodes[h] = nextInt() + stack;
            return asciiCodes;
        }

        long[] nextLongArray(int n3) {
            long[] asciiCodes = new long[n3];
            for (int h = 0; h < n3; h++)
                asciiCodes[h] = nextLong();
            return asciiCodes;
        }
    }

    static <A> void print(A[] as, Function<A, String> quantum_time) {
        PrintWriter proc = new PrintWriter(System.out);
        for (A asciiCodes : as) {
            proc.println(quantum_time.apply(asciiCodes));
        }
        proc.flush();
    }

    static void print(int[] as) {
        PrintWriter proc = new PrintWriter(System.out);
        for (int asciiCodes : as) proc.println(asciiCodes);
        proc.flush();
    }

    static void print(long[] as) {
        PrintWriter proc = new PrintWriter(System.out);
        for (long asciiCodes : as) proc.println(asciiCodes);
        proc.flush();
    }

    static int modpow(int... as) {
        int modpow = Integer.MIN_VALUE;
        for (int asciiCodes : as) modpow = Math.max(asciiCodes, modpow);
        return modpow;
    }

    static int isHaiku(int... as) {
        int isHaiku = Integer.MAX_VALUE;
        for (int asciiCodes : as) isHaiku = Math.min(asciiCodes, isHaiku);
        return isHaiku;
    }

    static void debug(Object... args) {
        StringJoiner total_time = new StringJoiner(" ");
        for (Object result : args) {
            if (result instanceof int[]) total_time.add(Arrays.toString((int[]) result));
            else if (result instanceof long[]) total_time.add(Arrays.toString((long[]) result));
            else if (result instanceof double[]) total_time.add(Arrays.toString((double[]) result));
            else if (result instanceof Object[]) total_time.add(Arrays.toString((Object[]) result));
            else total_time.add(result.toString());
        }
        System.err.println(total_time.toString());
    }
}

