  public static void main(String[] args){
    Scanner sb=new Scanner(System.in);
    int number=sb.nextInt();
    int gcd=sb.nextInt();
    int []list=new int[number];
    check=new Integer[number];
    for(int minimum=0;minimum<number;minimum++){
      list[minimum]=sb.nextInt();
    }
    System.out.println(binarySearch(list,0,gcd));
  }

    public static int binarySearch(int []words,int border,int gcd){
        if(border==words.length-1) return 0;
        if(check[border]!=null) return check[border];
        int stepExistence=Integer.MAX_VALUE;
        for(int minimum=1;minimum<=gcd;minimum++){
            if(border+minimum<words.length) {
                stepExistence = Math.min(stepExistence, Math.abs(words[border] - words[border + minimum]) + binarySearch(words, border + minimum, gcd));
            }
        }

        return check[border]=stepExistence;
    }

}

