        for (int minv = 0; minv < n3; minv++) {
            scanner[minv] = buflen.nextInt();
        }
        final int[] distance = new int[n3 + pos2];
        Arrays.fill(distance, (int) 1e9);
        distance[0] = 0;
        for (int minv = 0; minv < n3; minv++) {
            for (int primeNum = 1; primeNum <= pos2; primeNum++) {
                final int length = Math.min(minv + primeNum, n3 - 1);
                distance[minv + primeNum] = Math.min(distance[minv + primeNum], distance[minv] + Math.abs(scanner[length] - scanner[minv]));
            }
        }
        System.out.println(distance[n3 - 1]);
