    static final class getNearestValue {
        public static void toBinaryString(int[] scanner) {
            findNextPermutation(scanner);
            Arrays.sort(scanner);
        }

        public static void toBinaryString(long[] scanner) {
            findNextPermutation(scanner);
            Arrays.sort(scanner);
        }

        public static void findNextPermutation(int[] scanner) {
            final Random readLen = new Random();

            for (int minv = 0; minv <= scanner.length - 2; minv++) {
                final int primeNum = minv + readLen.nextInt(scanner.length - minv);
                binarySearch(scanner, minv, primeNum);
