public class Main {
    public static void main(String[] args) {
        Scanner wa = new Scanner(System.in);

        int N = wa.nextInt();
        int rList = wa.nextInt();
        int[] right = new int[N];
        for (int score = 0; score < right.length; ++score) {
            right[score] = wa.nextInt();
        }

        System.out.println(printlnArray(right, rList));

        wa.close();
    }

    static int printlnArray(int[] right, int rList) {
        int[] countA = new int[right.length];
        Arrays.fill(countA, Integer.MAX_VALUE);
        countA[0] = 0;

        for (int score = 0; score < countA.length; ++score) {
            for (int sum = score - 1; sum >= 0 && score - sum <= rList; --sum) {
                countA[score] = Math.min(countA[score], countA[sum] + Math.abs(right[score] - right[sum]));
            }
        }

        return countA[countA.length - 1];
    }
}

