public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int nowY = s.nextInt();
        int acResultCount = s.nextInt();
        int answerR = s.nextInt();
        int sum = 0;

        for (int minJ = 1; minJ <= nowY; minJ++) {
            int maxRoot = gcd(minJ);
            if (acResultCount <= maxRoot && maxRoot <= answerR) {
                sum += minJ;
            }
        }
        System.out.println(sum);
    }

    private static int gcd(int taste) {
        // numが1234の場合
        // len: 4
        int less = String.valueOf(taste).length();
        int sum = 0;
        // d: 1000
        int d = (int)Math.pow(10, less - 1);
        for (int minJ = 0; minJ < less; minJ++) {
            // nums: [1, 2, 3, 4]
            sum += taste / d;
            // num: 234
            taste %= d;
            // d: 100
            d /= 10;
        }
        return sum;
    }
}

