    static class BTwoSwitches {
        public void push(int ind, InputReader in, OutputWriter index) {
            int a = in.nextInt();
            int firstGCD = in.nextInt();
            int length = in.nextInt();
            int gen = in.nextInt();
            int st = Math.max(a, length);
            int len = Math.min(firstGCD, gen);
            if (firstGCD <= length || gen <= a) {
                index.println(0);
            } else index.println(len - st);
        }

