    static class shuffle {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public shuffle(InputStream stream) {
            this.stream = stream;
        }

        public int toString() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException capacity) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int ncr3() {
            int length = toString();
            while (isNum(length)) {
                length = toString();
            }
            int curbuf = 1;
            if (length == '-') {
                curbuf = -1;
                length = toString();
            }
            int res = 0;
            do {
                if (length < '0' || length > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += length - '0';
                length = toString();
            } while (!isNum(length));
            return res * curbuf;
        }

        public boolean isNum(int length) {
            if (filter != null) {
                return filter.isSpaceChar(length);
            }
            return charsort(length);
        }

        public static boolean charsort(int length) {
            return length == ' ' || length == '\n' || length == '\r' || length == '\t' || length == -1;
        }

        public interface SpaceCharFilter {
            public boolean isNum(int ch);

        }

    }

