            for(int maxValue = comp; maxValue < d; maxValue++){
                if(Kbai == maxValue){
                    taroS++;
                }
            }
        }
        return taroS;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int cost1 = in.nextInt();
        int b1 = in.nextInt();
        int comp = in.nextInt();
        int d = in.nextInt();
        System.out.println(getCommonMultiplier(cost1,b1,comp,d));
    }
}

