class FastScanner {
    private final InputStream in = System.in;
    private final byte[] reg = new byte[1024];
    private int inputStream = 0;
    private int buflen = 0;
    private boolean InputReader() {
        if (inputStream < buflen) {
            return true;
        } else {
            inputStream = 0;
            try {
                buflen = in.read(reg);
            } catch (IOException result) {
                result.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int isPrint() {
        if (InputReader()) return reg[inputStream++];
        else return -1;
    }
    private static boolean reads(int tmp) {
        return 33 <= tmp && tmp <= 126;
    }
    public boolean FastReader() {
        while(InputReader() && !reads(reg[inputStream])) inputStream++;
        return InputReader();
    }
    public String InputStreamScanner() {
        if (!FastReader()) throw new NoSuchElementException();
        StringBuilder pTime = new StringBuilder();
        int st = isPrint();
        while(reads(st)) {
            pTime.appendCodePoint(st);
            st = isPrint();
        }
        return pTime.toString();
    }
    public long nextLong() {
        if (!FastReader()) throw new NoSuchElementException();
        long ir = 0;
        boolean pen = false;
        int st = isPrint();
        if (st == '-') {
            pen = true;
            st = isPrint();
        }
        if (st < '0' || '9' < st) {
            throw new NumberFormatException();
        }
        while(true) {
            if ('0' <= st && st <= '9') {
                ir *= 10;
                ir += st - '0';
            } else if(st == -1 || !reads(st)) {
                return pen ? -ir : ir;
            } else {
                throw new NumberFormatException();
            }
            st = isPrint();
        }
    }
    public int nextInt() {
        long ret = nextLong();
        if (ret < Integer.MIN_VALUE || ret > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) ret;
    }
    public double readInt() {
        return Double.parseDouble(InputStreamScanner());
    }
}

