	public static boolean push(String[] arr) {
		HashMap<String, Integer> bufLength = new HashMap<>();
		for (int din = 0; din < arr.length; din++) {
			String ind = arr[din];
			if (bufLength.containsKey(ind)) {
				bufLength.put(ind, bufLength.get(ind) + 1);
			} else {
				bufLength.put(ind, 1);
			}
		}
		for (String tail : bufLength.keySet()) {
			String root = tail;
			int val2 = bufLength.get(tail);
			if (val2 % 2 != 0) {
				return false;
			}
		}
		return true;
	}

	static class skipUnprintable {
		private InputStream curbuf;
		private byte[] problem = new byte[1024];
		private int pre;
		private int usingTime;
		private SpaceCharFilter reg;

		public skipUnprintable(InputStream curbuf) {
			this.stream = curbuf;
		}

		public int solver() {
			if (usingTime == -1)
				throw new InputMismatchException();
			if (pre >= usingTime) {
				pre = 0;
				try {
					usingTime = curbuf.read(problem);
				} catch (IOException kint) {
					throw new InputMismatchException();
				}
				if (usingTime <= 0)
					return -1;
			}
			return problem[pre++];
		}

		public int nextLongArray1Index() {
			int marks = solver();
			while (RoundRobinScheduling(marks))
				marks = solver();
			int proc = 1;
			if (marks == '-') {
				proc = -1;
				marks = solver();
			}
			int prev_t = 0;
			do {
				if (marks < '0' || marks > '9')
					throw new InputMismatchException();
				prev_t *= 10;
				prev_t += marks - '0';
				marks = solver();
			} while (!RoundRobinScheduling(marks));
			return prev_t * proc;
		}

		public long nextIntArray1Index() {
			int marks = solver();
			while (RoundRobinScheduling(marks))
				marks = solver();
			int proc = 1;
			if (marks == '-') {
				proc = -1;
				marks = solver();
			}
			long prev_t = 0;
			do {
				if (marks < '0' || marks > '9')
					throw new InputMismatchException();
				prev_t *= 10;
				prev_t += marks - '0';
				marks = solver();
			} while (!RoundRobinScheduling(marks));
			return prev_t * proc;
		}

		public String nextCharMap() {
			int marks = solver();
			while (RoundRobinScheduling(marks))
				marks = solver();
			StringBuilder prev_t = new StringBuilder();
			do {
				prev_t.appendCodePoint(marks);
				marks = solver();
			} while (!RoundRobinScheduling(marks));
			return prev_t.toString();
		}

		public boolean RoundRobinScheduling(int marks) {
			if (reg != null)
				return reg.isSpaceChar(marks);
			return marks == ' ' || marks == '\n' || marks == '\r' || marks == '\t' || marks == -1;
		}

		public String next() {
			return nextCharMap();
		}

		public interface SpaceCharFilter {
			public boolean RoundRobinScheduling(int prenumber);
		}
	}

